// Validar input do usuário baseado no tipo de edição

const session = $('BUSCAR SESSAO ATIVA').first().json;
const post = $('BUSCAR POST').first().json;
const userInput = $('TRIGGER MENSAGEM').first().json.message.text;
const editType = session.edit_type;

let isValid = true;
let errors = [];
let sanitizedValue = userInput.trim();

// Validações por tipo
switch (editType) {
  case 'title':
    // Título: 10-120 caracteres, sem caracteres especiais problemáticos
    if (sanitizedValue.length < 10) {
      isValid = false;
      errors.push('Título muito curto (mínimo 10 caracteres)');
    }
    if (sanitizedValue.length > 120) {
      isValid = false;
      errors.push('Título muito longo (máximo 120 caracteres)');
    }
    if (/[<>{}\[\]]/.test(sanitizedValue)) {
      isValid = false;
      errors.push('Título contém caracteres inválidos');
    }
    break;

  case 'tags':
    // Tags: separadas por vírgula, 1-10 tags, cada tag 2-30 chars
    const tags = sanitizedValue.split(',').map(t => t.trim().toLowerCase()).filter(t => t.length > 0);
    if (tags.length === 0) {
      isValid = false;
      errors.push('Informe pelo menos uma tag');
    }
    if (tags.length > 10) {
      isValid = false;
      errors.push('Máximo de 10 tags permitido');
    }
    for (const tag of tags) {
      if (tag.length < 2) {
        isValid = false;
        errors.push(`Tag "${tag}" muito curta (mínimo 2 caracteres)`);
      }
      if (tag.length > 30) {
        isValid = false;
        errors.push(`Tag "${tag}" muito longa (máximo 30 caracteres)`);
      }
    }
    // Sanitiza para array JSON
    sanitizedValue = JSON.stringify(tags);
    break;

  case 'content':
    // Conteúdo: mínimo 50 caracteres (descrição das alterações)
    if (sanitizedValue.length < 20) {
      isValid = false;
      errors.push('Descreva as alterações com mais detalhes (mínimo 20 caracteres)');
    }
    if (sanitizedValue.length > 2000) {
      isValid = false;
      errors.push('Descrição muito longa (máximo 2000 caracteres)');
    }
    break;
}

// Prepara valores para preview
let originalValue = '';
let previewLabel = '';

switch (editType) {
  case 'title':
    originalValue = post.title || '';
    previewLabel = 'Título';
    break;
  case 'tags':
    originalValue = Array.isArray(post.tags) ? post.tags.join(', ') : (post.tags || '');
    previewLabel = 'Tags';
    // Para preview, mostra como lista
    if (isValid) {
      sanitizedValue = JSON.parse(sanitizedValue).join(', ');
    }
    break;
  case 'content':
    originalValue = 'Conteúdo atual do post';
    previewLabel = 'Alterações solicitadas';
    break;
}

return {
  json: {
    isValid,
    errors,
    editType,
    previewLabel,
    originalValue,
    newValue: sanitizedValue,
    rawInput: userInput,
    session_id: session.session_id,
    post_id: session.post_id,
    chat_id: session.chat_id,
    message_id: session.message_id,
    post_title: post.title
  }
};

// Formatar mensagem de preview com comparação

const data = $('VALIDAR INPUT').first().json;

let message = `✏️ *PREVIEW DA EDIÇÃO*\n━━━━━━━━━━━━━━━━━━━━━\n\n`;
message += `📝 *Campo:* ${data.previewLabel}\n\n`;

if (data.editType !== 'content') {
  message += `📤 *Valor atual:*\n_${data.originalValue.substring(0, 100)}${data.originalValue.length > 100 ? '...' : ''}_\n\n`;
  message += `📥 *Novo valor:*\n*${data.newValue.substring(0, 100)}${data.newValue.length > 100 ? '...' : ''}*\n\n`;
} else {
  message += `📋 *Alterações solicitadas:*\n_${data.newValue.substring(0, 200)}${data.newValue.length > 200 ? '...' : ''}_\n\n`;
  message += `⚠️ _O conteúdo será processado por AI_\n\n`;
}

message += `━━━━━━━━━━━━━━━━━━━━━\n`;
message += `_Confirma esta alteração?_`;

// Botões de confirmação
const postId = data.post_id;
const inlineKeyboard = [
  [
    { text: '✅ Confirmar', callback_data: `qe_confirm_${postId}` },
    { text: '✏️ Refazer', callback_data: `qe_redo_${postId}` }
  ],
  [
    { text: '❌ Cancelar', callback_data: `qe_cancel_${postId}` }
  ]
];

return {
  json: {
    chat_id: data.chat_id,
    text: message,
    parse_mode: 'Markdown',
    reply_markup: JSON.stringify({ inline_keyboard: inlineKeyboard })
  }
};
